<?php $feed = ClientApi::data($api->request('GET', 'api/videos?page=1&per_page=20')); $videos = is_array($feed['items'] ?? null) ? $feed['items'] : []; ?>
<section class="panel"><h2>Partager une vidéo</h2><p>MP4, WebM ou MOV, 100 Mo maximum. La vidéo est publiée après validation de l’équipe.</p><form method="post" enctype="multipart/form-data" class="comment-form"><?= client_csrf_field() ?><input type="hidden" name="action" value="video_upload"><label>Titre<input name="title" maxlength="180" required></label><label>Description<textarea name="description" maxlength="2000"></textarea></label><label>Fichier vidéo<input type="file" name="video" accept="video/mp4,video/webm,video/quicktime" required></label><label class="quiz-answer"><input type="checkbox" name="rights_confirmed" value="1" required> Je confirme disposer des droits nécessaires à la diffusion de cette vidéo.</label><button class="btn" type="submit">Envoyer pour validation</button></form></section>
<section class="feature-grid"><?php foreach ($videos as $video): ?><article class="panel video-card"><?php if (!empty($video['miniature_url'])): ?><img src="<?= client_h($video['miniature_url']) ?>" alt="<?= client_h($video['titre'] ?? '') ?>" loading="lazy"><?php endif; ?><h2><?= client_h($video['titre'] ?? '') ?></h2><p><?= client_h($video['description'] ?? '') ?></p><small>Par <?= client_h($video['auteur'] ?? '') ?> <?= !empty($video['destination']) ? '· ' . client_h($video['destination']) : '' ?></small><?php if (!empty($video['media_url'])): ?><video controls preload="metadata" src="<?= client_h($video['media_url']) ?>">Votre navigateur ne prend pas en charge la vidéo.</video><?php endif; ?><div class="feature-actions"><span><?= (int)($video['likes'] ?? 0) ?> réactions · <?= (int)($video['commentaires'] ?? 0) ?> commentaires</span><form method="post"><?= client_csrf_field() ?><input type="hidden" name="action" value="video_like"><input type="hidden" name="id" value="<?= (int)$video['id'] ?>"><button class="btn btn-quiet" type="submit">J’aime</button></form></div><?php $comments = ClientApi::data($api->request('GET', 'api/videos/' . (int)$video['id'] . '/comments')); if (is_array($comments) && $comments): ?><div class="video-comments"><h3>Commentaires</h3><?php foreach (array_slice($comments,0,5) as $comment): ?><p><strong><?= client_h($comment['auteur'] ?? '') ?></strong> · <?= client_h($comment['contenu'] ?? '') ?></p><?php endforeach; ?></div><?php endif; ?><form method="post" class="comment-form"><?= client_csrf_field() ?><input type="hidden" name="action" value="video_comment"><input type="hidden" name="id" value="<?= (int)$video['id'] ?>"><label>Commenter<textarea name="comment" maxlength="2000" required></textarea></label><button class="btn" type="submit">Publier</button></form></article><?php endforeach; ?></section><?php if (!$videos): ?><div class="panel empty"><p>Aucune vidéo publiée actuellement.</p></div><?php endif; ?>
